import{nearestBassSample,bassEnvelope}from'./bass.js';
import{tempoMap,secondsAt,clickEvents}from'./engine.js';
import{pcm16,wavHeader}from'./wav.js';
// Short sine blips for the click stem, rendered here so WAV export needs no extra sample files.
export function clickSamples(rate=44100){const make=f=>{const n=Math.round(rate*.05),samples=new Float32Array(n*2);for(let i=0;i<n;i++){const v=Math.sin(2*Math.PI*f*i/rate)*Math.exp(-i/(rate*.008))*.7;samples[i*2]=samples[i*2+1]=v}return{rate,channels:2,samples}};return{'click-hi':make(1760),'click-lo':make(1320)}}
export function* renderWav(song,result,override,kitIn,part='mix'){const rate=44100,channels=2,map=tempoMap(song,override),withDrums=part==='mix'||part==='drums'||part==='mixclick',withBass=part==='mix'||part==='bass'||part==='mixclick',withClick=part==='click'||part==='mixclick',kit=withClick?{...kitIn,...clickSamples(rate)}:kitIn;const notes=(withDrums?result.events:[]).map(e=>({frame:Math.round(secondsAt(e.beat,map)*rate),note:e.note,volume:2*(e.velocity/127)**1.3}));if(withClick)for(const e of result.clickEvents||clickEvents(song))notes.push({frame:Math.round(secondsAt(e.beat,map)*rate),note:e.accent?'click-hi':'click-lo',volume:e.accent?1:.75});if(withBass)for(const e of result.bassEvents||[]){const sample=nearestBassSample(e.note);notes.push({frame:Math.round(secondsAt(e.beat,map)*rate),note:'bass-'+sample,volume:1.65*(e.velocity/127)**1.3,speed:2**((e.note-sample)/12),duration:secondsAt(e.beat+e.duration,map)-secondsAt(e.beat,map)})}notes.sort((a,b)=>a.frame-b.frame);for(const n of notes){const s=kit[n.note];n.frames=n.duration!==undefined?Math.ceil((n.duration+.06)*rate):s?s.samples.length/2:0}let end=Math.ceil(secondsAt(song.length,map)*rate);for(const n of notes){const s=kit[n.note];if(s){if(s.rate!==rate||s.channels!==channels)throw Error('Unsupported drum sample format');end=Math.max(end,n.frame+n.frames)}}
 if(end/rate>600)throw Error('WAV รองรับเพลงยาวสูงสุด 10 นาที กรุณาแบ่งท่อนหรือใช้ MIDI');yield{header:wavHeader(end,rate,channels)};let next=0,active=[];
 for(let start=0;start<end;start+=rate){const count=Math.min(rate,end-start),out=new Float32Array(count*channels);while(next<notes.length&&notes[next].frame<start+count)active.push(notes[next++]);for(const n of active){const s=kit[n.note];if(!s)continue;const first=Math.max(start,n.frame),last=Math.min(start+count,n.frame+n.frames);for(let frame=first;frame<last;frame++){const dst=(frame-start)*2,age=frame-n.frame,pos=age*(n.speed||1),lo=Math.floor(pos),mix=pos-lo,volume=n.volume*(n.duration!==undefined?bassEnvelope(age/rate,n.duration):1);for(let ch=0;ch<2;ch++){const first=s.samples[lo*2+ch]||0,second=s.samples[(lo+1)*2+ch]||0;out[dst+ch]+=(first+(second-first)*mix)*volume}}}active=active.filter(n=>kit[n.note]&&n.frame+n.frames>start+count);for(let i=0;i<out.length;i++)out[i]=Math.tanh(out[i]*.8);yield{data:pcm16(out).buffer,progress:Math.min(1,(start+count)/end)}}
}
